/**
 * Purpose: the multilingual scenario material, taken verbatim from @breadcrumb/demo-seed —
 * 39 concepts with one-line summaries and four real conversations, written out by hand in
 * every language the interface ships in. Nothing here is generated by a model: test data an
 * LLM wrote would measure how well a model agrees with another model's idea of a learner.
 *
 * Two structural facts are used as ground truth and neither is invented here:
 *  - DEMO_GOAL_REQUIRES is the demo goal's hand-authored prerequisite DAG (ids, so it holds
 *    in every language);
 *  - the two domains (observational astronomy, JavaScript) share no learning structure, so a
 *    cross-domain pair is a genuine "unrelated" for the edge judge.
 *
 * Main exports: BENCH_LANGUAGES, demoConcepts, demoRounds, demoLongAnswer, demoRequiresPairs,
 * demoUnrelatedPairs, demoGoalTitle, ASTRO_CONCEPT_IDS, JS_CONCEPT_IDS.
 */
import {
  type ConceptId,
  DEMO_GOAL_REQUIRES,
  DEMO_TEXT_BY_LANGUAGE,
  demoTextFor,
} from "@breadcrumb/demo-seed";

/** Every language the demo learner speaks, in a fixed order so a run is reproducible. */
export const BENCH_LANGUAGES: readonly string[] = Object.keys(DEMO_TEXT_BY_LANGUAGE);

/** The astronomy half of the demo tree. Listed rather than derived because demo-seed keeps
 * the domain on its spec list, which is internal to that package — and the ConceptId union
 * makes a typo here a compile error, so the list cannot silently rot. */
export const ASTRO_CONCEPT_IDS = [
  "astro-root",
  "stellar-spectra",
  "parallax",
  "transits",
  "event-horizon",
  "tidal-locking",
  "kepler-laws",
  "magnitude-scale",
  "gravitational-lensing",
  "white-dwarf",
  "neutron-star",
  "cmb",
] as const satisfies readonly ConceptId[];

const ASTRO_SET: ReadonlySet<string> = new Set(ASTRO_CONCEPT_IDS);

export interface DemoConcept {
  id: ConceptId;
  label: string;
  summary: string;
  domain: "astro" | "js";
}

/** The 39 demo concepts as this language writes them, in demo-seed's own id order. */
export function demoConcepts(language: string): DemoConcept[] {
  const text = demoTextFor(language);
  return (Object.keys(text.concepts) as ConceptId[]).map((id) => {
    const words = text.concepts[id];
    return {
      id,
      label: words[0],
      summary: words[1],
      domain: ASTRO_SET.has(id) ? "astro" : "js",
    };
  });
}

/** The JavaScript half, derived from the astronomy list so the two can never overlap. */
export const JS_CONCEPT_IDS: readonly ConceptId[] = (
  Object.keys(demoTextFor("en").concepts) as ConceptId[]
).filter((id) => !ASTRO_SET.has(id));

export interface DemoRound {
  /** What the learner said. */
  question: string;
  /** What the companion answered. */
  answer: string;
  /** Concepts this exchange is actually about — the echo target for prose scoring. */
  concepts: string[];
}

/**
 * Six real exchanges per language: three from the astronomy conversation, two from the
 * JavaScript one, and the teach-back. The concepts each exchange touches are the ones
 * demo-seed itself attaches that turn's sightings to, so the "expected" labels are the demo's
 * own bookkeeping rather than a guess made here.
 */
export function demoRounds(language: string): DemoRound[] {
  const text = demoTextFor(language);
  const label = (id: ConceptId): string => text.concepts[id][0];
  const [a0, a1, a2, a3, a4, a5] = text.astroMessages;
  const [j0, j1, j2, j3] = text.jsMessages;
  const [t0, t1] = text.teachMessages;
  return [
    { question: a0, answer: a1, concepts: [label("gravitational-lensing")] },
    {
      question: a2,
      answer: a3,
      concepts: [label("stellar-spectra"), label("gravitational-lensing")],
    },
    {
      question: a4,
      answer: a5,
      concepts: [label("astro-root"), label("kepler-laws"), label("parallax")],
    },
    { question: j0, answer: j1, concepts: [label("js-root"), label("event-loop")] },
    { question: j2, answer: j3, concepts: [label("closures"), label("event-loop")] },
    { question: t0, answer: t1, concepts: [label("closures")] },
  ];
}

/** One conversation's answers joined in order — a long answer of the shape term marking and
 * focus stations actually run over, made of real turns rather than padded text. */
export function demoLongAnswer(language: string, conversation: "astro" | "js"): string {
  const text = demoTextFor(language);
  const turns =
    conversation === "astro"
      ? [text.astroMessages[1], text.astroMessages[3], text.astroMessages[5]]
      : [text.jsMessages[1], text.jsMessages[3]];
  return turns.join("\n\n");
}

export interface LabelledPair {
  aLabel: string;
  aSummary: string;
  bLabel: string;
  bSummary: string;
}

function conceptWords(language: string, id: ConceptId): { label: string; summary: string } {
  const words = demoTextFor(language).concepts[id];
  return { label: words[0], summary: words[1] };
}

/** The demo goal's hand-authored prerequisite edges, rendered in one language. `a` is always
 * the prerequisite, matching the gold file's convention. */
export function demoRequiresPairs(language: string): LabelledPair[] {
  return DEMO_GOAL_REQUIRES.map(([prerequisite, dependent]) => {
    const a = conceptWords(language, prerequisite);
    const b = conceptWords(language, dependent);
    return { aLabel: a.label, aSummary: a.summary, bLabel: b.label, bSummary: b.summary };
  });
}

/** Cross-domain pairs: an astronomy concept against a JavaScript one. Nothing in the demo
 * tree connects the two domains, so every pair here is an "unrelated" the judge should
 * reject. Paired by position and truncated to the shorter list, so the set is stable. */
export function demoUnrelatedPairs(language: string): LabelledPair[] {
  const count = Math.min(ASTRO_CONCEPT_IDS.length, JS_CONCEPT_IDS.length);
  return Array.from({ length: count }, (_, index) => {
    const astroId = ASTRO_CONCEPT_IDS[index] as ConceptId;
    const jsId = JS_CONCEPT_IDS[index] as ConceptId;
    const a = conceptWords(language, astroId);
    const b = conceptWords(language, jsId);
    return { aLabel: a.label, aSummary: a.summary, bLabel: b.label, bSummary: b.summary };
  });
}

/** The demo learner's one goal, as this language states it. */
export function demoGoalTitle(language: string): string {
  return demoTextFor(language).goalTitle;
}

/** The three sentences demo-seed met a vocabulary word in, with `{word}` still in place. */
export function demoWordContexts(language: string): readonly string[] {
  return demoTextFor(language).wordContexts;
}
